        balance = [0] * len(subs)
        cost = [0] * len(subs)

        # Calculate balance and cost for forward direction
        open_count = 0
        for i, char in enumerate(subs):
            if char in '([':
                open_count += 1
            else:
                if open_count > 0:
                    open_count -= 1
                else:
